mapper.select:
select r.id, r.reporter_id, r.target_type, r.target_id, r.report_reason, r.report_content, r.created_time, r.handle_status, u.username as reporter_name, u.avatar as reporter_avatar, CASE WHEN r.target_type = 1 THEN mu.music_name -- 音乐 WHEN r.target_type = 2 THEN c.content -- 评论 WHEN r.target_type = 3 THEN ud.username -- 普通用户 WHEN r.target_type = 4 THEN m.stage_name -- 音乐人 END as target_name, CASE WHEN r.target_type = 1 THEN mu.cover_url -- 音乐封面 WHEN r.target_type = 2 THEN ud.avatar -- 评论发布者头像 WHEN r.target_type = 3 THEN ud.avatar -- 普通用户头像 WHEN r.target_type = 4 THEN m.avatar -- 音乐人头像 END as target_avatar,
CASE WHEN r.target_type = 1 THEN IF(mu.status = 2, 0, 1) -- 音乐状态 WHEN r.target_type = 2 THEN IF(c.status = 0, 0, 1) -- 评论状态 WHEN r.target_type = 3 THEN ud.user_status -- 普通用户状态 WHEN r.target_type = 4 THEN m.status -- 音乐人状态 END as target_status from user_report as r left join user as u on r.reporter_id = u.id left join comment as c on r.target_type = 2 and r.target_id = c.id left join music as mu on r.target_type = 1 and r.target_id = mu.id left join user as ud on (r.target_type = 3 and r.target_id = ud.id) -- 普通用户 or (r.target_type = 2 and c.user_id = ud.id) -- 评论发布者 left join musician as m on r.target_type = 4 and r.target_id = m.id
r.handle_status = #{status}
and r.target_type = #{type}
and r.report_reason = #{reason}
and ( u.username like concat('%', #{key}, '%') or r.report_content like concat('%', #{key}, '%') or CASE WHEN r.target_type = 1 THEN mu.music_name WHEN r.target_type = 2 THEN c.content WHEN r.target_type = 3 THEN ud.username WHEN r.target_type = 4 THEN m.stage_name END like concat('%', #{key}, '%') )
order by r.created_time desc
